ValidationRule.errorConditionFormula:
AND(
$Profile.Name <> "System Administrator", TEXT($User.UserType) <> "AutomatedProcess", RecordType.DeveloperName = "Latam_Quality", NOT(ISPICKVAL(High_Potential_Risk__c, "No Risk")), NOT(ISPICKVAL(High_Potential_Risk__c, "")), AND(ISPICKVAL( Consumer_Profile__c ,""), ISPICKVAL( Body_Injuries__c , ""), ISPICKVAL( Emotional_Damages__c , ""), ISPICKVAL(Other_Situations__c ,""))
)
